import { headers } from "next/headers";
import { redirect } from "next/navigation";
import { auth } from "@/lib/auth";

export type User = {
  id: string;
  email: string;
  name: string;
  createdAt: string;
};

type AuthUser = { id: string; email: string; name: string; createdAt: Date };

function toUser(u: AuthUser): User {
  return {
    id: u.id,
    email: u.email,
    name: u.name,
    createdAt: new Date(u.createdAt).toISOString().slice(0, 10),
  };
}

export async function listUsers(): Promise<User[]> {
  const ctx = await auth.$context;
  const users = await ctx.internalAdapter.listUsers(undefined, undefined, {
    field: "createdAt",
    direction: "asc",
  });
