import Link from "next/link";
import { useRouter } from "next/navigation";
import { useState } from "react";
import { authClient } from "@/lib/auth-client";

type Props = {
  mode: "sign-in" | "sign-up";
  callbackURL: string;
  googleEnabled: boolean;
};

const inputClass =
  "w-full rounded-md border border-black/15 bg-transparent px-3 py-2 text-sm dark:border-white/20";

export function AuthForm({ mode, callbackURL, googleEnabled }: Props) {
  const router = useRouter();
  const [error, setError] = useState<string | null>(null);
  const [pending, setPending] = useState(false);
  const isSignUp = mode === "sign-up";

  async function onSubmit(event: React.FormEvent<HTMLFormElement>) {
    event.preventDefault();
    setError(null);
    setPending(true);

    const form = new FormData(event.currentTarget);
    const email = String(form.get("email"));
    const password = String(form.get("password"));

    const { error } = isSignUp
      ? await authClient.signUp.email({ name: String(form.get("name")), email, password })
      : await authClient.signIn.email({ email, password });

    if (error) {
      setError(error.message ?? "Something went wrong. Please try again.");
      setPending(false);
      return;
    }
    router.push(callbackURL);
    router.refresh();
  }

  async function onGoogle() {
    setError(null);
    setPending(true);
    const { error } = await authClient.signIn.social({ provider: "google", callbackURL });
    if (error) {
      setError(error.message ?? "Google sign-in failed.");
      setPending(false);
    }
  }

  const otherHref = `${isSignUp ? "/sign-in" : "/sign-up"}?callbackURL=${encodeURIComponent(callbackURL)}`;

  return (
    <main className="mx-auto w-full max-w-sm p-8">
      <h1 className="text-2xl font-semibold">{isSignUp ? "Create your Notely account" : "Sign in to Notely"}</h1>

      <form onSubmit={onSubmit} className="mt-6 space-y-3">
        {isSignUp && (
          <input name="name" placeholder="Name" required autoComplete="name" className={inputClass} />
        )}
        <input name="email" type="email" placeholder="Email" required autoComplete="email" className={inputClass} />
        <input
          name="password"
          type="password"
          placeholder="Password"
          required
          minLength={8}
          autoComplete={isSignUp ? "new-password" : "current-password"}
          className={inputClass}
        />
        {error && <p className="text-sm text-red-600">{error}</p>}
        <button
          type="submit"
          disabled={pending}
          className="w-full rounded-md bg-foreground px-3 py-2 text-sm font-medium text-background disabled:opacity-50"
        >
          {isSignUp ? "Sign up" : "Sign in"}
        </button>
      </form>

      {googleEnabled && (
        <button
          onClick={onGoogle}
          disabled={pending}
          className="mt-3 w-full rounded-md border border-black/15 px-3 py-2 text-sm font-medium disabled:opacity-50 dark:border-white/20"
        >
          Continue with Google
        </button>
      )}

      <p className="mt-6 text-sm opacity-70">
        {isSignUp ? "Already have an account? " : "No account yet? "}
        <Link href={otherHref} className="underline">
          {isSignUp ? "Sign in" : "Sign up"}
        </Link>
      </p>
    </main>
  );
}
EOF
